using BetaFit.Desktop.Controls;using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Forms;
public partial class FrmMain:Form {private readonly IBetaFitApiService? _api;private readonly Session? _session;public FrmMain():this(null,null){}public FrmMain(IBetaFitApiService? api,Session? session){_api=api;_session=session;InitializeComponent();if(_api!=null&&_session!=null){BuildShell();LoadControl(new UcDashboard(_api));}}private void BuildShell(){var sidebar=new UcSidebar();var header=new UcHeader(_api,_session);Controls.Add(header);Controls.Add(sidebar);sidebar.BringToFront();header.BringToFront();sidebar.DashboardClicked+=(_,_)=>LoadControl(new UcDashboard(_api));sidebar.ProductsClicked+=(_,_)=>LoadControl(new UcProducts(_api));sidebar.CategoriesClicked+=(_,_)=>LoadControl(new UcCategories(_api));sidebar.SettingsClicked+=(_,_)=>LoadControl(new UcSettings(_api,_session));sidebar.LogoutClicked+=(_,_)=>{_session?.SignOut();Close();};}private void LoadControl(UserControl control){pnlContent.Controls.Clear();control.Dock=DockStyle.Fill;pnlContent.Controls.Add(control);}}